#![cfg(all(windows,feature="producer-test-fixture"))]
use std::{io::Write,os::windows::process::CommandExt,path::Path,process::{Command,Stdio}};
use serde_json::{json,Value};

fn fixture()->std::path::PathBuf {let mut random=[0u8;16];getrandom::fill(&mut random).unwrap();let suffix:String=random.iter().map(|v|format!("{v:02x}")).collect();let base=Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("MindTrailExplicit-{suffix}"));std::fs::create_dir(&base).unwrap();base.join("state")}
fn invoke(root:&Path,queue:&str,id:&str,events:&[Value])->(bool,Value) {
    let mut child=Command::new(env!("CARGO_BIN_EXE_mindtrail-producer")).args(["submit-events","--queue",queue,"--batch-id",id]).env("MINDTRAIL_TEST_ROOT",root).creation_flags(0x08000000).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();
    child.stdin.take().unwrap().write_all(&serde_json::to_vec(events).unwrap()).unwrap();let output=child.wait_with_output().unwrap();let value=serde_json::from_slice(&output.stdout).unwrap_or_else(|_|panic!("invalid CLI output: {}",String::from_utf8_lossy(&output.stderr)));(output.status.success(),value)
}
fn event(session:&str,seq:u64)->Value {let (kind,payload)=match seq {1=>("task.start",json!({"title":"T","goal":"G","project":"P"})),2=>("capability.intent",json!({"id":"c","title":"C"})),3=>("task.done",json!({"summary":"end"})),_=>unreachable!()};json!({"v":1,"session":session,"seq":seq,"ts":"2024-01-01T00:00:00Z","type":kind,"payload":payload})}
fn read_events(root:&Path,session:&str)->Value {use std::io::{Read,Write};let discovery:Value=serde_json::from_slice(&std::fs::read(root.join("endpoint.json")).unwrap()).unwrap();let port=discovery["port"].as_u64().unwrap() as u16;let token=discovery["token"].as_str().unwrap();let mut stream=std::net::TcpStream::connect(("127.0.0.1",port)).unwrap();stream.set_read_timeout(Some(std::time::Duration::from_secs(3))).unwrap();write!(stream,"GET /v1/sessions/{session}/events HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nAuthorization: Bearer {token}\r\nConnection: close\r\n\r\n").unwrap();let mut response=String::new();stream.read_to_string(&mut response).unwrap();let (header,body)=response.split_once("\r\n\r\n").unwrap();assert!(header.starts_with("HTTP/1.1 200"));serde_json::from_str(body).unwrap()}
fn proxy_gateway(root:&Path,requests:usize,drop_post:bool)->(Vec<u8>,std::thread::JoinHandle<(Vec<Vec<u8>>,Vec<Value>)>) {
    use std::io::Read;let original=std::fs::read(root.join("endpoint.json")).unwrap();let mut discovery:Value=serde_json::from_slice(&original).unwrap();let gateway_port=discovery["port"].as_u64().unwrap() as u16;let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();discovery["port"]=json!(listener.local_addr().unwrap().port());std::fs::write(root.join("endpoint.json"),serde_json::to_vec(&discovery).unwrap()).unwrap();
    let thread=std::thread::spawn(move || {let mut posts=Vec::new();let mut receipts=Vec::new();for _ in 0..requests {let (mut incoming,_)=listener.accept().unwrap();incoming.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();let mut headers=Vec::new();let mut byte=[0u8];while !headers.ends_with(b"\r\n\r\n"){incoming.read_exact(&mut byte).unwrap();headers.push(byte[0]);}let text=String::from_utf8(headers).unwrap();let length=text.lines().find_map(|s|s.to_ascii_lowercase().strip_prefix("content-length: ").and_then(|n|n.parse::<usize>().ok())).unwrap_or(0);let mut body=vec![0;length];incoming.read_exact(&mut body).unwrap();let is_post=text.starts_with("POST ");if is_post {posts.push(body.clone());}
        let mut forward=std::net::TcpStream::connect(("127.0.0.1",gateway_port)).unwrap();forward.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();for line in text.lines().filter(|s|!s.is_empty()) {if line.to_ascii_lowercase().starts_with("host:"){write!(forward,"host: 127.0.0.1:{gateway_port}\r\n").unwrap()}else{write!(forward,"{line}\r\n").unwrap()}}write!(forward,"Connection: close\r\n\r\n").unwrap();forward.write_all(&body).unwrap();let mut response=Vec::new();forward.read_to_end(&mut response).unwrap();assert!(response.starts_with(b"HTTP/1.1 200"));if is_post {let index=response.windows(4).position(|v|v==b"\r\n\r\n").unwrap()+4;receipts.push(serde_json::from_slice(&response[index..]).unwrap());}if !(drop_post && is_post){incoming.write_all(&response).unwrap();}}
        (posts,receipts)});(original,thread)
}
fn scripted_gateway(root:&Path,replies:Vec<(u16,Value)>)->std::thread::JoinHandle<Vec<String>> {
    use std::io::Read;let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let port=listener.local_addr().unwrap().port();std::fs::write(root.join("endpoint.json"),serde_json::to_vec(&json!({"version":1,"port":port,"token":"a".repeat(64),"store_id":"b".repeat(64)})).unwrap()).unwrap();
    std::thread::spawn(move || {listener.set_nonblocking(true).unwrap();let mut paths=Vec::new();for (status,body) in replies {let deadline=std::time::Instant::now()+std::time::Duration::from_secs(8);let mut stream=loop {match listener.accept(){Ok((s,_))=>break s,Err(e) if e.kind()==std::io::ErrorKind::WouldBlock && std::time::Instant::now()<deadline=>std::thread::yield_now(),Err(e)=>panic!("scripted gateway: {e}")}};stream.set_nonblocking(false).unwrap();stream.set_read_timeout(Some(std::time::Duration::from_secs(3))).unwrap();let mut head=Vec::new();let mut byte=[0];while !head.ends_with(b"\r\n\r\n"){stream.read_exact(&mut byte).unwrap();head.push(byte[0]);}let head=String::from_utf8(head).unwrap();paths.push(head.lines().next().unwrap().to_owned());let len=head.lines().find_map(|s|s.to_ascii_lowercase().strip_prefix("content-length: ").and_then(|v|v.parse::<usize>().ok())).unwrap_or(0);let mut input=vec![0;len];stream.read_exact(&mut input).unwrap();let body=body.to_string();write!(stream,"HTTP/1.1 {status} Test\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len()).unwrap();}paths})
}
fn raw(root:&Path,args:&[&str],input:&[u8])->(bool,Value) {let mut child=Command::new(env!("CARGO_BIN_EXE_mindtrail-producer")).args(args).env("MINDTRAIL_TEST_ROOT",root).creation_flags(0x08000000).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(input).unwrap();let output=child.wait_with_output().unwrap();let value=serde_json::from_slice(&output.stdout).expect("exactly one JSON response");(output.status.success(),value)}
#[test] fn cli_offline_admission_validation_and_counts() {
    let root=fixture();let one=event("offline",1);let request=serde_json::to_vec(&vec![one.clone()]).unwrap();
    for args in [&["submit-events","--batch-id","a"][..],&["submit-events","--queue","sample"][..],&["submit-events","--queue","sample","--batch-id"," "][..],&["flush","--queue","sample","--unknown","x"][..]] {let (ok,value)=raw(&root,args,b"");assert!(!ok);assert!(value.get("error").is_some());}
    let (ok,first)=raw(&root,&["submit-events","--queue","sample","--batch-id","one"],&request);assert!(ok);assert_eq!(first["status"],"queued");assert_eq!(first["session"],"offline");
    let (ok,again)=raw(&root,&["submit-events","--queue","sample","--batch-id","one"],&request);assert!(ok);assert_eq!(again,first);
    let mut changed=one.clone();changed["payload"]["title"]=json!("changed");let (ok,conflict)=invoke(&root,"sample","one",&[changed]);assert!(!ok);assert_eq!(conflict["error"]["code"],"batch_conflict");
    let mut other=event("other",2);other["session"]=json!("other");let (ok,_)=invoke(&root,"sample","mixed",&[one.clone(),other]);assert!(!ok);
    let (ok,_)=invoke(&root,"sample","descending",&[event("z",3),event("z",2)]);assert!(!ok);
    let (ok,too_large)=raw(&root,&["submit-events","--queue","sample","--batch-id","large"],&vec![b' ';1024*1024+1]);assert!(!ok);assert_eq!(too_large["error"]["code"],"payload_too_large");
    let mut exact=request.clone();exact.resize(1024*1024,b' ');let (ok,boundary)=raw(&root,&["submit-events","--queue","boundary","--batch-id","exact"],&exact);assert!(ok);assert_eq!(boundary["status"],"queued");
    let events:Vec<Value>=(1..=201).map(|seq|json!({"v":1,"session":"many","seq":seq,"ts":"2024-01-01T00:00:00Z","type":"capability.intent","payload":{"id":format!("c{seq}"),"title":"C"}})).collect();let (ok,too_many)=invoke(&root,"sample","too-many",&events);assert!(!ok);assert_eq!(too_many["error"]["code"],"invalid_request");
    let (ok,counts)=raw(&root,&["flush","--queue","sample"],b"");assert!(ok);assert_eq!(counts,json!({"committed":0,"pending":1,"blocked":0}));
}
#[test] fn gap_after_existing_prefix_replays_missing_batch() {
    let root=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let a=event("after",1);let b=event("after",2);let c=event("after",3);
    assert_eq!(invoke(&root,"sample","one",&[a]).1["status"],"committed");let (ok,gap)=invoke(&root,"sample","three",&[c.clone()]);assert!(!ok);assert_eq!(gap["error"]["code"],"seq_gap");assert_eq!(gap["error"]["last_seq"],1);assert_eq!(gap["error"]["expected_seq"],2);assert_eq!(gap["error"]["offending_seq"],3);
    let (ok,repaired)=invoke(&root,"sample","two",&[b]);assert!(ok,"{repaired}");assert_eq!(repaired["receipt"]["duplicates"],1);let original=invoke(&root,"sample","three",&[c]).1;assert_eq!(original["status"],"committed");assert_eq!(original["receipt"]["accepted"],1);gateway.shutdown().unwrap();
}
#[test] fn gap_inside_first_transaction_repairs_rolled_back_prefix() {
    let root=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let a=event("inside",1);let b=event("inside",2);let c=event("inside",3);
    let (ok,gap)=invoke(&root,"sample","original",&[a.clone(),c.clone()]);assert!(!ok);assert_eq!(gap["error"]["code"],"seq_gap");assert_eq!(gap["error"]["last_seq"],0);assert_eq!(gap["error"]["expected_seq"],2);assert_eq!(gap["error"]["offending_seq"],3);
    let (ok,second)=invoke(&root,"sample","two",&[b]);assert!(ok,"{second}");assert_eq!(second["receipt"]["duplicates"],1);let original=invoke(&root,"sample","original",&[a,c]).1;assert_eq!(original["receipt"]["accepted"],1);assert_eq!(original["receipt"]["duplicates"],1);assert_eq!(original["receipt"]["last_seq"],3);gateway.shutdown().unwrap();
}
#[test] fn missing_prefix_is_not_partially_sent_and_repair_chunks_at_200() {
    let root=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let session="chunks";let base=|seq:u64,kind:&str,payload:Value|json!({"v":1,"session":session,"seq":seq,"ts":"2024-01-01T00:00:00Z","type":kind,"payload":payload});
    let start=base(1,"task.start",json!({"title":"T","goal":"G","project":"P"}));let done=base(203,"task.done",json!({}));assert_eq!(invoke(&root,"sample","start",&[start]).1["status"],"committed");assert_eq!(invoke(&root,"sample","end",&[done.clone()]).1["error"]["code"],"seq_gap");
    let prefix:Vec<Value>=(2..202).map(|seq|base(seq,"capability.intent",json!({"id":format!("c{seq}"),"title":"C"}))).collect();let (ok,blocked)=invoke(&root,"sample","first-200",&prefix);assert!(!ok);assert_eq!(blocked["error"]["code"],"session_blocked");assert_eq!(read_events(&root,session)["events"].as_array().unwrap().len(),1);
    let last=base(202,"capability.intent",json!({"id":"c202","title":"C"}));let (ok,result)=invoke(&root,"sample","last",&[last]);assert!(ok,"{result}");assert_eq!(result["receipt"]["duplicates"],1);let original=invoke(&root,"sample","end",&[done]).1;assert_eq!(original["receipt"]["last_seq"],203);let original_prefix=invoke(&root,"sample","first-200",&prefix).1;assert_eq!(original_prefix["receipt"]["duplicates"],200);gateway.shutdown().unwrap();
}
#[test] fn repair_chunks_at_body_size_limit() {
    let root=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let make=|seq:u64,kind:&str,payload:Value|json!({"v":1,"session":"bytes","seq":seq,"ts":"2024-01-01T00:00:00Z","type":kind,"payload":payload});
    let start=make(1,"task.start",json!({"title":"T","goal":"G","project":"P"}));let last=make(4,"task.done",json!({}));let second=make(2,"capability.intent",json!({"id":"a","title":"A","quote":"x".repeat(600_000)}));let third=make(3,"capability.intent",json!({"id":"b","title":"B","quote":"y".repeat(600_000)}));
    assert_eq!(invoke(&root,"sample","start",&[start]).1["status"],"committed");assert_eq!(invoke(&root,"sample","last",&[last.clone()]).1["error"]["code"],"seq_gap");assert_eq!(invoke(&root,"sample","second",&[second]).1["error"]["code"],"session_blocked");let (ok,result)=invoke(&root,"sample","third",&[third]);assert!(ok,"{result}");assert_eq!(invoke(&root,"sample","last",&[last]).1["status"],"committed");
    let db=rusqlite::Connection::open_with_flags(root.join("producers/explicit/sample/queue.sqlite3"),rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();let (count,max):(u64,u64)=db.query_row("SELECT count(*),max(length(request)) FROM repairs",[],|r|Ok((r.get(0)?,r.get(1)?))).unwrap();assert_eq!(count,2);assert!(max<=1024*1024);gateway.shutdown().unwrap();
}
#[test] fn rejected_session_does_not_block_another_session() {
    let root=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let make=|session:&str,seq:u64,kind:&str,payload:Value|json!({"v":1,"session":session,"seq":seq,"ts":"2024-01-01T00:00:00Z","type":kind,"payload":payload});
    let a1=make("a",1,"task.start",json!({"title":"A","goal":"G","project":"P"}));let a2=make("a",2,"task.done",json!({}));assert_eq!(invoke(&root,"sample","a1",&[a1]).1["status"],"committed");assert_eq!(invoke(&root,"sample","a2",&[a2]).1["status"],"committed");
    let a3=make("a",3,"capability.intent",json!({"id":"a3","title":"A"}));assert_eq!(invoke(&root,"sample","a3",&[a3]).1["error"]["code"],"task_closed");let a4=make("a",4,"capability.intent",json!({"id":"a4","title":"A"}));assert_eq!(invoke(&root,"sample","a4",&[a4]).1["error"]["code"],"session_blocked");
    let b1=make("b",1,"task.start",json!({"title":"B","goal":"G","project":"P"}));assert_eq!(invoke(&root,"sample","b1",&[b1]).1["status"],"committed");let (ok,counts)=raw(&root,&["flush","--queue","sample"],b"");assert!(ok);assert_eq!(counts,json!({"committed":3,"pending":0,"blocked":2}));gateway.shutdown().unwrap();
}
#[test] fn same_original_batch_can_reveal_later_gap() {
    let root=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let make=|seq:u64,kind:&str,payload:Value|json!({"v":1,"session":"gaps","seq":seq,"ts":"2024-01-01T00:00:00Z","type":kind,"payload":payload});
    let a=make(1,"task.start",json!({"title":"T","goal":"G","project":"P"}));let b=make(2,"capability.intent",json!({"id":"b","title":"B"}));let c=make(3,"capability.intent",json!({"id":"c","title":"C"}));let d=make(4,"capability.intent",json!({"id":"d","title":"D"}));let e=make(5,"task.done",json!({}));
    let batch=vec![a,c,e];assert_eq!(invoke(&root,"sample","original",&batch).1["error"]["expected_seq"],2);let result=invoke(&root,"sample","two",&[b]);assert!(!result.0);assert_eq!(result.1["error"]["code"],"session_blocked");let gap=invoke(&root,"sample","original",&batch).1;assert_eq!(gap["error"]["expected_seq"],4);assert_eq!(gap["error"]["last_seq"],2);
    assert!(invoke(&root,"sample","four",&[d]).0);let result=invoke(&root,"sample","original",&batch).1;assert_eq!(result["receipt"]["accepted"],1);assert_eq!(result["receipt"]["duplicates"],2);assert_eq!(result["receipt"]["last_seq"],5);gateway.shutdown().unwrap();
}
#[test] fn gateway_commit_with_lost_response_retries_original_bytes() {
    use std::io::Read;
    let root=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let original_discovery=std::fs::read(root.join("endpoint.json")).unwrap();let mut discovery:Value=serde_json::from_slice(&original_discovery).unwrap();let gateway_port=discovery["port"].as_u64().unwrap() as u16;
    let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let proxy_port=listener.local_addr().unwrap().port();discovery["port"]=json!(proxy_port);std::fs::write(root.join("endpoint.json"),serde_json::to_vec(&discovery).unwrap()).unwrap();
    let proxy=std::thread::spawn(move || {let mut captured=Vec::new();for index in 0..2 {let (mut incoming,_)=listener.accept().unwrap();incoming.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();let mut headers=Vec::new();let mut byte=[0u8];while !headers.ends_with(b"\r\n\r\n"){incoming.read_exact(&mut byte).unwrap();headers.push(byte[0]);}let text=String::from_utf8(headers).unwrap();let len=text.lines().find_map(|s|s.to_ascii_lowercase().strip_prefix("content-length: ").and_then(|n|n.parse::<usize>().ok())).unwrap_or(0);let mut body=vec![0;len];incoming.read_exact(&mut body).unwrap();if index==1 {captured=body.clone();}let mut forward=std::net::TcpStream::connect(("127.0.0.1",gateway_port)).unwrap();forward.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();for line in text.lines().filter(|s|!s.is_empty()) {if line.to_ascii_lowercase().starts_with("host:"){write!(forward,"host: 127.0.0.1:{gateway_port}\r\n").unwrap()}else{write!(forward,"{line}\r\n").unwrap()}}write!(forward,"Connection: close\r\n\r\n").unwrap();forward.write_all(&body).unwrap();let mut response=Vec::new();forward.read_to_end(&mut response).unwrap();assert!(response.starts_with(b"HTTP/1.1 200"));if index==0 {incoming.write_all(&response).unwrap();}}
        captured});
    let event=event("lost",1);let expected=serde_json::to_vec(&vec![event.clone()]).unwrap();let (ok,queued)=invoke(&root,"sample","same",&[event.clone()]);assert!(ok);assert_eq!(queued["status"],"queued");assert_eq!(proxy.join().unwrap(),expected);std::fs::write(root.join("endpoint.json"),original_discovery).unwrap();let (ok,retry)=invoke(&root,"sample","same",&[event]);assert!(ok,"{retry}");assert_eq!(retry["receipt"]["accepted"],0);assert_eq!(retry["receipt"]["duplicates"],1);assert_eq!(read_events(&root,"lost")["events"].as_array().unwrap().len(),1);gateway.shutdown().unwrap();
}
#[test] fn repair_commit_with_lost_response_replays_exact_chunk_and_confirms_original() {
    let root=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let a=event("repairlost",1);let b=event("repairlost",2);let c=event("repairlost",3);
    assert_eq!(invoke(&root,"sample","one",&[a]).1["status"],"committed");assert_eq!(invoke(&root,"sample","three",&[c.clone()]).1["error"]["code"],"seq_gap");
    let (original,first)=proxy_gateway(&root,2,true);let (ok,pending)=invoke(&root,"sample","two",&[b]);assert!(ok,"{pending}");assert_eq!(pending["status"],"queued");let (sent,first_receipts)=first.join().unwrap();assert_eq!(sent.len(),1);assert_eq!(first_receipts[0],json!({"accepted":1,"duplicates":0,"last_seq":2}));std::fs::write(root.join("endpoint.json"),&original).unwrap();assert_eq!(read_events(&root,"repairlost")["events"].as_array().unwrap().len(),2);
    let db=rusqlite::Connection::open_with_flags(root.join("producers/explicit/sample/queue.sqlite3"),rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();let (stored,status):(Vec<u8>,String)=db.query_row("SELECT request,status FROM repairs ORDER BY id LIMIT 1",[],|r|Ok((r.get(0)?,r.get(1)?))).unwrap();assert_eq!(stored,sent[0]);assert_eq!(status,"pending");drop(db);
    let (original,second)=proxy_gateway(&root,6,false);let (ok,counts)=raw(&root,&["flush","--queue","sample"],b"");assert!(ok,"{counts}");assert_eq!(counts,json!({"committed":3,"pending":0,"blocked":0}));let (retried,receipts)=second.join().unwrap();assert_eq!(retried.len(),3);assert_eq!(retried[0],sent[0]);assert_eq!(receipts[0],json!({"accepted":0,"duplicates":1,"last_seq":2}));std::fs::write(root.join("endpoint.json"),original).unwrap();let result=invoke(&root,"sample","three",&[c]).1;assert_eq!(result["receipt"]["accepted"],1);assert_eq!(result["receipt"]["duplicates"],0);assert_eq!(read_events(&root,"repairlost")["events"].as_array().unwrap().len(),3);gateway.shutdown().unwrap();
}
#[test] fn retryable_503_does_not_block_another_session() {
    let root=fixture();assert!(invoke(&root,"sample","a",&[event("a",1)]).0);assert!(invoke(&root,"sample","b",&[event("b",1)]).0);
    let health=json!({"version":1,"store_id":"b".repeat(64)});let server=scripted_gateway(&root,vec![(200,health.clone()),(503,json!({})),(200,health),(200,json!({"accepted":1,"duplicates":0,"last_seq":1}))]);
    let (ok,counts)=raw(&root,&["flush","--queue","sample"],b"");assert!(ok);assert_eq!(counts,json!({"committed":1,"pending":1,"blocked":0}));assert_eq!(server.join().unwrap(),vec!["GET /v1/health HTTP/1.1","POST /v1/events HTTP/1.1","GET /v1/health HTTP/1.1","POST /v1/events HTTP/1.1"]);
}
#[test] fn mixed_401_pauses_all_sessions_for_same_snapshot() {
    let root=fixture();assert!(invoke(&root,"sample","a",&[event("a",1)]).0);assert!(invoke(&root,"sample","b",&[event("b",1)]).0);
    let health=json!({"version":1,"store_id":"b".repeat(64)});let server=scripted_gateway(&root,vec![(200,health),(401,json!({})),(401,json!({}))]);
    let (ok,counts)=raw(&root,&["flush","--queue","sample"],b"");assert!(ok);assert_eq!(counts,json!({"committed":0,"pending":2,"blocked":0}));assert_eq!(server.join().unwrap(),vec!["GET /v1/health HTTP/1.1","POST /v1/events HTTP/1.1","GET /v1/health HTTP/1.1"]);
}
#[test] fn old_receipt_remains_available_after_later_repair_rejected() {
    let root=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let first=event("old",1);let third=event("old",3);let original=invoke(&root,"sample","first",&[first.clone()]).1;assert_eq!(original["status"],"committed");assert_eq!(invoke(&root,"sample","third",&[third]).1["error"]["code"],"seq_gap");
    let foreign=json!({"v":1,"session":"old","seq":2,"ts":"2024-01-01T00:00:00Z","type":"task.done","payload":{}});assert_eq!(invoke(&root,"other","foreign",&[foreign]).1["status"],"committed");
    let missing=event("old",2);let (ok,blocked)=invoke(&root,"sample","missing",&[missing]);assert!(!ok);assert_eq!(blocked["error"]["code"],"session_blocked");let (ok,again)=invoke(&root,"sample","first",&[first]);assert!(ok,"{again}");assert_eq!(again,original);gateway.shutdown().unwrap();
}
#[test] fn successful_long_session_rotates_to_other_session() {
    use std::io::Read;
    let root=fixture();for (id,batch) in [("a1",vec![event("a",1)]),("a2",vec![event("a",2)]),("a3",vec![event("a",3)]),("b1",vec![event("b",1)])] {assert!(invoke(&root,"sample",id,&batch).0);}
    let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let port=listener.local_addr().unwrap().port();std::fs::write(root.join("endpoint.json"),serde_json::to_vec(&json!({"version":1,"port":port,"token":"a".repeat(64),"store_id":"b".repeat(64)})).unwrap()).unwrap();
    let server=std::thread::spawn(move || {let mut sessions=Vec::new();for _ in 0..8 {let (mut stream,_)=listener.accept().unwrap();stream.set_read_timeout(Some(std::time::Duration::from_secs(3))).unwrap();let mut head=Vec::new();let mut byte=[0];while !head.ends_with(b"\r\n\r\n"){stream.read_exact(&mut byte).unwrap();head.push(byte[0]);}let head=String::from_utf8(head).unwrap();let len=head.lines().find_map(|line|line.to_ascii_lowercase().strip_prefix("content-length: ").and_then(|v|v.parse::<usize>().ok())).unwrap_or(0);let mut body=vec![0;len];stream.read_exact(&mut body).unwrap();let response=if head.starts_with("POST "){let batch:Value=serde_json::from_slice(&body).unwrap();sessions.push(batch[0]["session"].as_str().unwrap().to_owned());std::thread::sleep(std::time::Duration::from_millis(80));json!({"accepted":1,"duplicates":0,"last_seq":batch[0]["seq"]})}else{json!({"version":1,"store_id":"b".repeat(64)})}.to_string();write!(stream,"HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{response}",response.len()).unwrap();}sessions});
    let (ok,result)=raw(&root,&["flush","--queue","sample"],b"");assert!(ok,"{result}");assert_eq!(result,json!({"committed":4,"pending":0,"blocked":0}));assert_eq!(server.join().unwrap(),vec!["a","b","a","a"]);
}
